# Convert RGB565 to RGB888
def rgb565_to_rgb888(rgb565):
    red = (rgb565 >> 11) & 0x1F
    green = (rgb565 >> 5) & 0x3F
    blue = rgb565 & 0x1F

    # Scale to 8-bit range
    red = (red << 3) | (red >> 2)
    green = (green << 2) | (green >> 4)
    blue = (blue << 3) | (blue >> 2)

    return red, green, blue

# Create a 3D NumPy array for the RGB888 image
height_rgb565 = len(rgb565_image)
width_rgb565 = len(rgb565_image[0])
rgb888_image = np.zeros((height_rgb565, width_rgb565, 3), dtype=np.uint8)

for y in range(height_rgb565):
    for x in range(width_rgb565):
        rgb888_image[y, x] = rgb565_to_rgb888(rgb565_image[y][x])

# Convert grayscale image to a NumPy array
grayscale_array = np.array(grayscale_image)

# Plot the images side by side
fig, axes = plt.subplots(1, 2, figsize=(10, 5))

# Display RGB888 image
axes[0].imshow(rgb888_image, interpolation="nearest")
axes[0].set_title("RGB565 image", fontproperties=prop)
axes[0].grid(True, which="both", color="gray", linestyle="--", linewidth=0.5)
axes[0].tick_params(axis='both', which='major', labelsize=10)

# Display Grayscale image
im = axes[1].imshow(grayscale_array, cmap="gray", interpolation="nearest")
axes[1].set_title("96x96 grayscale image", fontproperties=prop)
axes[1].grid(True, which="both", color="gray", linestyle="--", linewidth=0.5)
axes[1].tick_params(axis='both', which='major', labelsize=10)

# Add colorbar for grayscale image
fig.colorbar(im, ax=axes[1])

# Save and display the plot
plt.tight_layout()
plt.savefig(image_path, dpi=300, bbox_inches='tight')
plt.show()